import { readFileSync } from "node:fs";
import path from "node:path";
import { UPLOAD_DIR } from "./db";

/**
 * Applicant-tracking-system submission adapters.
 *
 * Each ATS publishes a real write API, but all three require a credential that
 * only the *employer* can issue:
 *
 * - Greenhouse: `POST /v1/boards/{board}/jobs/{id}` with HTTP Basic auth using
 *   the employer's Job Board API key.
 * - Lever: `POST /v0/postings/{site}/{postingId}?key=…` with a key generated by
 *   a Super Admin of that company's Lever account.
 * - Ashby: `applicationForm.submit` with a key holding the `candidatesWrite`
 *   permission, plus the employer's published application-form definition.
 *
 * A candidate cannot self-issue these keys. The adapters therefore only run
 * when the matching credential is configured, never invent answers to required
 * questions, and only report `verified` when the ATS returns a reference.
 */

export type AtsName = "greenhouse" | "lever" | "ashby";

export type AtsTarget = {
  ats: AtsName;
  board: string;
  postingId: string;
  endpoint: string;
};

export type AtsCredential = { kind: AtsName; key: string };

export type AtsSubmission = {
  target: AtsTarget;
  job: { title: string; company: string; url: string | null; application_url: string | null };
  profile: {
    full_name: string | null;
    email: string | null;
    phone: string | null;
    location: string | null;
    headline: string | null;
    linkedin: string | null;
    website: string | null;
    work_authorisation: string | null;
  };
  documents: {
    cvPath: string | null;
    cvName: string | null;
    coverPath: string | null;
    coverName: string | null;
    coverText: string | null;
  };
  at: string;
};

export type AtsResult = {
  status: "verified" | "unverified" | "failed" | "blocked";
  detail: string;
  httpStatus: number | null;
  reference: string | null;
  endpoint: string;
  evidence: Record<string, unknown>;
};

const TIMEOUT_MS = 45_000;

/** Job fields that map onto verified profile data, so no answer is invented. */
const SUPPORTED_GREENHOUSE_FIELDS = new Set([
  "first_name",
  "last_name",
  "email",
  "phone",
  "resume",
  "resume_text",
  "cover_letter",
  "cover_letter_text",
  "location",
  "linkedin",
  "website",
]);

function credentialFor(ats: AtsName): string | null {
  const raw =
    ats === "greenhouse"
      ? process.env.GREENHOUSE_JOB_BOARD_API_KEY
      : ats === "lever"
        ? process.env.LEVER_POSTINGS_API_KEY
        : process.env.ASHBY_API_KEY;
  const key = (raw ?? "").trim();
  return key ? key : null;
}

export function atsCredential(ats: AtsName): AtsCredential | null {
  const key = credentialFor(ats);
  return key ? { kind: ats, key } : null;
}

/** Why a discovered ATS vacancy cannot be submitted automatically. */
export function atsCredentialReason(ats: AtsName): string {
  if (ats === "greenhouse") {
    return "Greenhouse submissions require the employer's Greenhouse Job Board API key, which a candidate cannot self-issue. The package is complete and queued for the employer's hosted application form.";
  }
  if (ats === "lever") {
    return "Lever submissions require a postings API key issued by that employer's Lever Super Admin. The package is complete and queued for the employer's hosted application form.";
  }
  return "Ashby submissions require an API key with candidatesWrite plus the employer's application-form definition. The package is complete and queued for the employer's hosted application form.";
}

function targetFromSource(source: string | null | undefined, externalId: string | null | undefined): AtsTarget | null {
  if (!source || !externalId) return null;
  const [kind, board] = source.split(":");
  if (!board) return null;
  if (kind === "greenhouse") {
    return {
      ats: "greenhouse",
      board,
      postingId: externalId,
      endpoint: `https://boards-api.greenhouse.io/v1/boards/${encodeURIComponent(board)}/jobs/${encodeURIComponent(externalId)}`,
    };
  }
  if (kind === "lever") {
    return {
      ats: "lever",
      board,
      postingId: externalId,
      endpoint: `https://api.lever.co/v0/postings/${encodeURIComponent(board)}/${encodeURIComponent(externalId)}`,
    };
  }
  if (kind === "ashby") {
    return { ats: "ashby", board, postingId: externalId, endpoint: "https://api.ashbyhq.com/applicationForm.submit" };
  }
  return null;
}

function targetFromUrl(raw: string | null | undefined): AtsTarget | null {
  if (!raw) return null;
  let url: URL;
  try {
    url = new URL(raw);
  } catch {
    return null;
  }
  const host = url.hostname.toLowerCase();
  const parts = url.pathname.split("/").filter(Boolean);
  if (/(?:^|\.)greenhouse\.io$/.test(host) && parts.length >= 3 && parts[1] === "jobs") {
    const [board, , postingId] = parts;
    return {
      ats: "greenhouse",
      board,
      postingId,
      endpoint: `https://boards-api.greenhouse.io/v1/boards/${encodeURIComponent(board)}/jobs/${encodeURIComponent(postingId)}`,
    };
  }
  if (host === "jobs.ashbyhq.com" && parts.length >= 2) {
    return { ats: "ashby", board: parts[0], postingId: parts[1], endpoint: "https://api.ashbyhq.com/applicationForm.submit" };
  }
  if ((host === "jobs.lever.co" || host === "jobs.eu.lever.co") && parts.length >= 2) {
    const hostPrefix = host === "jobs.eu.lever.co" ? "https://api.eu.lever.co" : "https://api.lever.co";
    return {
      ats: "lever",
      board: parts[0],
      postingId: parts[1],
      endpoint: `${hostPrefix}/v0/postings/${encodeURIComponent(parts[0])}/${encodeURIComponent(parts[1])}`,
    };
  }
  return null;
}

export function atsTargetFor(job: {
  application_url?: string | null;
  url?: string | null;
  source?: string | null;
  external_id?: string | null;
}): AtsTarget | null {
  return targetFromSource(job.source, job.external_id) ?? targetFromUrl(job.application_url) ?? targetFromUrl(job.url);
}

function fileFor(relativePath: string | null): { buffer: Buffer; name: string } | null {
  if (!relativePath) return null;
  const name = path.basename(relativePath);
  try {
    return { buffer: readFileSync(path.join(UPLOAD_DIR, name)), name };
  } catch {
    return null;
  }
}

function splitName(fullName: string | null): { first: string; last: string } {
  const parts = (fullName ?? "").trim().split(/\s+/).filter(Boolean);
  if (parts.length === 0) return { first: "", last: "" };
  if (parts.length === 1) return { first: parts[0], last: "" };
  return { first: parts[0], last: parts.slice(1).join(" ") };
}

/** Accepts the identifiers the ATSes actually return; strings or numeric ids. */
export function atsReference(payload: unknown): string | null {
  if (!payload || typeof payload !== "object") return null;
  const record = payload as Record<string, unknown>;
  const containers = [record, (record.results ?? {}) as Record<string, unknown>, (record.application ?? {}) as Record<string, unknown>];
  for (const container of containers) {
    for (const key of ["reference", "confirmation", "confirmationId", "applicationId", "application_id", "id"]) {
      const value = container[key];
      if (typeof value === "string" && value.trim()) return value.trim().slice(0, 300);
      if (typeof value === "number" && Number.isFinite(value)) return String(value);
    }
  }
  return null;
}

async function readBody(response: Response): Promise<{ text: string; parsed: unknown }> {
  const text = (await response.text().catch(() => "")).slice(0, 4000);
  try {
    return { text, parsed: JSON.parse(text) };
  } catch {
    return { text, parsed: text };
  }
}

function missingProfile(profile: AtsSubmission["profile"]): string | null {
  if (!profile.full_name?.trim()) return "The verified profile has no full name.";
  if (!profile.email?.trim() || !profile.email.includes("@")) return "The verified profile has no usable email address.";
  return null;
}

async function submitGreenhouse(input: AtsSubmission, credential: AtsCredential): Promise<AtsResult> {
  const { endpoint, postingId } = input.target;
  const questionsResponse = await fetch(`${endpoint}?questions=true`, {
    headers: { Accept: "application/json", "User-Agent": "AT-AI-Workforce/2.2 (authorised submission)" },
    signal: AbortSignal.timeout(TIMEOUT_MS),
    cache: "no-store",
  });
  if (!questionsResponse.ok) {
    return {
      status: "blocked",
      detail: `Greenhouse posting ${postingId} responded HTTP ${questionsResponse.status} when its application form was read, so nothing was sent.`,
      httpStatus: questionsResponse.status,
      reference: null,
      endpoint,
      evidence: { ats: "greenhouse", instant: input.at, httpStatus: questionsResponse.status },
    };
  }
  const { parsed } = await readBody(questionsResponse);
  const form = ((parsed as { questions?: Array<{ label?: string; required?: boolean; fields?: Array<{ name?: string }> }> }).questions ?? []);
  const required = form.filter((question) => question.required);
  const unsupported = required.filter(
    (question) => !(question.fields ?? []).every((field) => SUPPORTED_GREENHOUSE_FIELDS.has(String(field.name ?? ""))),
  );
  if (unsupported.length > 0) {
    const labels = unsupported.map((question) => question.label ?? "unlabelled question").slice(0, 5);
    return {
      status: "blocked",
      detail: `Greenhouse requires answers this application cannot evidence (${labels.join("; ")}), so no answer was invented and nothing was sent.`,
      httpStatus: questionsResponse.status,
      reference: null,
      endpoint,
      evidence: { ats: "greenhouse", instant: input.at, requiredQuestions: labels },
    };
  }

  const { first, last } = splitName(input.profile.full_name);
  const body = new FormData();
  body.set("first_name", first);
  body.set("last_name", last);
  body.set("email", input.profile.email ?? "");
  if (input.profile.phone) body.set("phone", input.profile.phone);
  if (input.profile.location) body.set("location", input.profile.location);
  if (input.profile.linkedin) body.set("linkedin", input.profile.linkedin);
  if (input.profile.website) body.set("website", input.profile.website);
  if (input.documents.coverText) body.set("cover_letter_text", input.documents.coverText.slice(0, 12_000));
  const cv = fileFor(input.documents.cvPath);
  if (cv) body.set("resume", new Blob([new Uint8Array(cv.buffer)], { type: "application/pdf" }), cv.name);
  const cover = fileFor(input.documents.coverPath);
  if (cover) body.set("cover_letter", new Blob([new Uint8Array(cover.buffer)], { type: "application/pdf" }), cover.name);

  const response = await fetch(endpoint, {
    method: "POST",
    body,
    headers: {
      Authorization: `Basic ${Buffer.from(`${credential.key}:`).toString("base64")}`,
      "User-Agent": "AT-AI-Workforce/2.2 (authorised submission)",
    },
    signal: AbortSignal.timeout(TIMEOUT_MS),
    cache: "no-store",
  });
  const { text, parsed: payload } = await readBody(response);
  if (!response.ok) {
    return {
      status: response.status === 408 || response.status === 429 || response.status >= 500 ? "failed" : "blocked",
      detail: `Greenhouse rejected the application with HTTP ${response.status}. Nothing was recorded as submitted.`,
      httpStatus: response.status,
      reference: null,
      endpoint,
      evidence: { ats: "greenhouse", instant: input.at, httpStatus: response.status, responseSnippet: text.slice(0, 600) },
    };
  }
  const reference = atsReference(payload);
  return {
    status: reference ? "verified" : "unverified",
    detail: reference
      ? `Greenhouse accepted the application for posting ${postingId} with reference ${reference}.`
      : `Greenhouse returned HTTP ${response.status} without an application reference, so the submission is unverified.`,
    httpStatus: response.status,
    reference,
    endpoint,
    evidence: {
      ats: "greenhouse",
      board: input.target.board,
      postingId,
      instant: input.at,
      httpStatus: response.status,
      responseSnippet: text.slice(0, 1200),
      files: [cv?.name, cover?.name].filter(Boolean),
    },
  };
}

async function submitLever(input: AtsSubmission, credential: AtsCredential): Promise<AtsResult> {
  const { endpoint } = input.target;
  const url = `${endpoint}?key=${encodeURIComponent(credential.key)}`;
  const body = new FormData();
  body.set("name", input.profile.full_name ?? "");
  body.set("email", input.profile.email ?? "");
  if (input.profile.phone) body.set("phone", input.profile.phone);
  if (input.profile.linkedin) body.set("urls[LinkedIn]", input.profile.linkedin);
  if (input.profile.website) body.set("urls[Portfolio]", input.profile.website);
  if (input.documents.coverText) body.set("comments", input.documents.coverText.slice(0, 12_000));
  const cv = fileFor(input.documents.cvPath);
  if (cv) body.set("resume", new Blob([new Uint8Array(cv.buffer)], { type: "application/pdf" }), cv.name);

  const response = await fetch(url, {
    method: "POST",
    body,
    headers: { "User-Agent": "AT-AI-Workforce/2.2 (authorised submission)" },
    signal: AbortSignal.timeout(TIMEOUT_MS),
    cache: "no-store",
  });
  const { text, parsed: payload } = await readBody(response);
  if (!response.ok) {
    return {
      status: response.status === 408 || response.status === 429 || response.status >= 500 ? "failed" : "blocked",
      detail: `Lever rejected the application with HTTP ${response.status}. Nothing was recorded as submitted.`,
      httpStatus: response.status,
      reference: null,
      endpoint,
      evidence: { ats: "lever", instant: input.at, httpStatus: response.status, responseSnippet: text.slice(0, 600) },
    };
  }
  const reference = atsReference(payload);
  return {
    status: reference ? "verified" : "unverified",
    detail: reference
      ? `Lever accepted the application for posting ${input.target.postingId} with reference ${reference}.`
      : `Lever returned HTTP ${response.status} without an application reference, so the submission is unverified.`,
    httpStatus: response.status,
    reference,
    endpoint,
    evidence: {
      ats: "lever",
      board: input.target.board,
      postingId: input.target.postingId,
      instant: input.at,
      httpStatus: response.status,
      responseSnippet: text.slice(0, 1200),
      files: cv?.name ? [cv.name] : [],
    },
  };
}

async function submitAshby(input: AtsSubmission, credential: AtsCredential): Promise<AtsResult> {
  const { endpoint, postingId } = input.target;
  const { first, last } = splitName(input.profile.full_name);
  // Ashby's public contract takes the employer's form definition. Only standard
  // fields are sent; a rejection is recorded verbatim rather than guessed around.
  const payload = {
    jobPostingId: postingId,
    applicationForm: {
      firstName: first,
      lastName: last,
      email: input.profile.email ?? "",
      phone: input.profile.phone ?? "",
      linkedInUrl: input.profile.linkedin ?? "",
      websiteUrl: input.profile.website ?? "",
      resumeText: input.documents.coverText ?? "",
    },
  };
  const response = await fetch(endpoint, {
    method: "POST",
    body: JSON.stringify(payload),
    headers: {
      Authorization: `Basic ${Buffer.from(`${credential.key}:`).toString("base64")}`,
      "Content-Type": "application/json",
      "User-Agent": "AT-AI-Workforce/2.2 (authorised submission)",
    },
    signal: AbortSignal.timeout(TIMEOUT_MS),
    cache: "no-store",
  });
  const { text, parsed } = await readBody(response);
  if (!response.ok) {
    return {
      status: response.status === 429 || response.status >= 500 ? "failed" : "blocked",
      detail: `Ashby rejected the application with HTTP ${response.status}; the employer's form may require fields this package cannot evidence. Nothing was recorded as submitted.`,
      httpStatus: response.status,
      reference: null,
      endpoint,
      evidence: { ats: "ashby", instant: input.at, httpStatus: response.status, responseSnippet: text.slice(0, 600) },
    };
  }
  const reference = atsReference(parsed);
  return {
    status: reference ? "verified" : "unverified",
    detail: reference
      ? `Ashby accepted the application for posting ${postingId} with reference ${reference}.`
      : `Ashby returned HTTP ${response.status} without an application reference, so the submission is unverified.`,
    httpStatus: response.status,
    reference,
    endpoint,
    evidence: { ats: "ashby", postingId, instant: input.at, httpStatus: response.status, responseSnippet: text.slice(0, 1200) },
  };
}

export async function submitViaAts(input: AtsSubmission, credential: AtsCredential): Promise<AtsResult> {
  const missing = missingProfile(input.profile);
  if (missing) {
    return {
      status: "blocked",
      detail: `${missing} Nothing was sent.`,
      httpStatus: null,
      reference: null,
      endpoint: input.target.endpoint,
      evidence: { ats: input.target.ats, instant: input.at, missing: "profile" },
    };
  }
  try {
    if (input.target.ats === "greenhouse") return await submitGreenhouse(input, credential);
    if (input.target.ats === "lever") return await submitLever(input, credential);
    return await submitAshby(input, credential);
  } catch (error) {
    const message = error instanceof Error ? error.message : "unknown transport error";
    return {
      status: "failed",
      detail: `The ${input.target.ats} submission could not be delivered: ${message}`,
      httpStatus: null,
      reference: null,
      endpoint: input.target.endpoint,
      evidence: { ats: input.target.ats, instant: input.at, error: message },
    };
  }
}
